  async function load(){if(window.SECTION_LAB_CATALOG)return window.SECTION_LAB_CATALOG;if(loading)return loading;loading=(async()=>{const response=await fetch('questions/section-lab-data.json.gz');if(!response.ok)throw Error('Section explorations could not be loaded.');let bytes=new Uint8Array(await response.arrayBuffer());if(bytes[0]===31&&bytes[1]===139){if(typeof DecompressionStream!=='function')throw Error('This browser needs gzip decompression support to load section explorations.');const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));bytes=new Uint8Array(await new Response(stream).arrayBuffer());}const parsed=JSON.parse(new TextDecoder().decode(bytes));if(!Array.isArray(parsed.sections))throw Error('Section catalog is invalid.');window.SECTION_LAB_CATALOG=parsed;return parsed;})().catch(error=>{loading=null;throw error;});return loading;}
